const inc = $('Get PD Incident').first().json.incident;
return [{ json: {
  incident_id:    inc.id,
  incident_title: inc.title,
  occurred_at:    inc.created_at,
  pd_url:         inc.html_url,
  status:         inc.status,
  urgency:        inc.urgency
}}];

const title = ($('Extract Incident Context').first().json.incident_title ?? '').toLowerCase();
const alerts = $('Get PD Alerts').first().json?.alerts ?? [];
const alertsStr = JSON.stringify(alerts).toLowerCase();
const hasLogMetric = alertsStr.includes('logging.googleapis.com/user/') || alertsStr.includes('log_based_metric');
const titleSignal = title.includes('gke') || title.includes('log-based') || title.includes('log metric') || title.includes('error rate') || title.includes('error count');
const is_gke_log_alert = hasLogMetric || titleSignal;
const metricType = (alerts[0]?.body?.details?.incident?.metric?.type ?? alerts[0]?.body?.details?.metric?.type ?? '');
const metric_name = metricType.replace('logging.googleapis.com/user/', '');
return [{ json: { is_gke_log_alert, metric_name, hasLogMetric, titleSignal, metricType } }];

const inc = $('Extract Incident Context').first().json;
const start = new Date(new Date(inc.occurred_at).getTime() - 60*60*1000).toISOString();
const end   = new Date(new Date(inc.occurred_at).getTime() + 30*60*1000).toISOString();
let metricFilter = null;
try { metricFilter = $('Get Log Metric Definition').first().json.filter ?? null; } catch(e) {}
const baseFilter = metricFilter
  ? '(' + metricFilter + ') AND timestamp>="' + start + '" AND timestamp<="' + end + '"'
  : 'resource.type="k8s_container" AND resource.labels.project_id="YOUR_GCP_PROJECT_ID" AND resource.labels.namespace_name=(YOUR_K8S_NAMESPACES_GCP_OR) AND severity>="WARNING" AND timestamp>="' + start + '" AND timestamp<="' + end + '"';
return [{ json: {
  resourceNames: ['projects/cio-logging-storage-1b866dc7/locations/northamerica-northeast1/buckets/logsink_bucket_kitchen_sink/views/_AllLogs'],
  filter: baseFilter,
  orderBy: 'timestamp desc',
  pageSize: 100
}}];

const entries = $input.first().json.entries ?? [];
const byContainer = {};
for (const e of entries) {
  const key = (e.resource?.labels?.container_name ?? 'unknown') + '/' + (e.severity ?? 'DEFAULT');
  byContainer[key] = (byContainer[key] ?? 0) + 1;
}
const topMessages = entries.slice(0, 30).map(e => ({
  ts:        e.timestamp,
  sev:       e.severity,
  container: e.resource?.labels?.container_name,
  pod:       e.resource?.labels?.pod_name,
  msg: (e.textPayload ?? e.jsonPayload?.message ?? e.jsonPayload?.msg ?? '').slice(0, 400)
}));
const errorCodes = [...new Set(
  entries.flatMap(e => (e.textPayload ?? e.jsonPayload?.message ?? '').match(/[A-Z_]{4,}/g) ?? [])
)].slice(0, 20);
return [{ json: {
  total_entries: entries.length,
  by_container:  byContainer,
  error_tokens:  errorCodes,
  entries:       topMessages
}}];
